function isKneeStrength(e){return e.region==='Rodilla'&&e.block==='Fuerza'}
function exerciseTags(e){if(!isKneeStrength(e))return {muscleGroups:[],dominance:'',family:''};const hint=suggestedExerciseTags[e.id]||{};return {muscleGroups:Array.isArray(e.muscleGroups)?e.muscleGroups:hint.muscleGroups||[],dominance:e.dominance!==undefined?e.dominance:hint.dominance||'',family:String(e.taxonomyVersion?e.family||'':e.family||hint.family||'').trim()}}
function syncSubgroupFilters(prefix,reg,work){const active=reg==='Rodilla'&&work==='Fuerza';['muscle','dominance','family'].forEach(key=>{const el=$('#'+prefix+'-'+key);if(el){el.hidden=!active;el.disabled=!active;if(!active)el.value=''}});return active}
function muscleFilters(prefix,muscle='',dominance=''){return `<select id="${prefix}-muscle" aria-label="Grupo muscular"><option value="">Todos los grupos musculares</option>${muscleGroupNames.map(x=>`<option ${x===muscle?'selected':''}>${esc(x)}</option>`).join('')}<option value="unclassified" ${muscle==='unclassified'?'selected':''}>Sin clasificar</option></select><select id="${prefix}-dominance" aria-label="Dominante del movimiento"><option value="">Cadera y rodilla · todos</option><option value="Cadera" ${dominance==='Cadera'?'selected':''}>Dominante de cadera</option><option value="Rodilla" ${dominance==='Rodilla'?'selected':''}>Dominante de rodilla</option></select>`}
function matchesMuscle(e,muscle,dominance){const t=exerciseTags(e);return (!muscle||(muscle==='unclassified'?!t.muscleGroups.length:t.muscleGroups.includes(muscle)))&&(!dominance||t.dominance===dominance)}
function exerciseTagLabel(e){const t=exerciseTags(e);return [...t.muscleGroups,t.dominance?'Dominante de '+t.dominance.toLowerCase():''].join(' · ')}

