function imageCard(e,i){const yt=youtubeId(e.url);return `<div class="exercise-image block-${blocks.indexOf(e.block)}">${yt?`<img class="thumb" src="https://i.ytimg.com/vi/${yt}/hqdefault.jpg" alt="" loading="lazy">`:illustration(e.art??i)}<span class="exercise-badge">${blockSymbol(e.block)} ${esc(e.block)}</span><span class="play">${icon('play')}</span><span class="source-badge">${e.url?(e.source==='youtube'?'YouTube':e.source==='file'?'Video propio':'Video externo'):'Imagen de referencia'}</span></div>`}
function renderLibrary(){shell(`<section class="movement-hero"><div class="movement-copy"><span class="eyebrow">EJERCICIO TERAPÉUTICO · PLANIFICACIÓN INDIVIDUAL</span><h1>BIENVENIDO</h1><p>Seleccioná los ejercicios. Personalizá las indicaciones.<br>Acompañá a cada paciente también fuera del consultorio.</p><div class="hero-actions">${btn('Crear una rutina','new-routine','','plus')}<button class="hero-library-link" data-action="scroll-library">Explorar biblioteca ${icon('down')}</button></div><div class="hero-signature"><span class="signature-line"></span> Tomás Bossio · Plan de rutina</div></div><div class="movement-visual"><img src="assets/movement-hero.webp" alt="Imagen decorativa de un hombre y una mujer haciendo ejercicio, con baja opacidad sobre un fondo azul" fetchpriority="high"><span class="floating-label label-top"><span class="label-icon">${icon('video')}</span><span>Biblioteca de ejercicios<strong>Organizada y reutilizable</strong></span></span><span class="floating-label label-bottom"><span class="label-icon coral">${icon('check')}</span><span>Rutinas individuales<strong>Indicaciones precisas</strong></span></span><span class="visual-caption">EJERCICIO · FUNCIÓN · MOVIMIENTO</span></div></section><div class="workspace-strip"><div><span class="strip-icon">${icon('video')}</span><strong>${data.exercises.length.toString().padStart(2,'0')}</strong><span>ejercicios en tu biblioteca</span></div><div><span class="strip-icon peach">${icon('users')}</span><strong>${data.routines.length.toString().padStart(2,'0')}</strong><span>planes individuales</span></div><div><span class="strip-icon lilac">${icon('grid')}</span><strong>${String(blocks.length).padStart(2,'0')}</strong><span>formas de trabajar</span></div><span class="strip-caption">CRITERIO CLÍNICO. ATENCIÓN PERSONAL.</span></div><section id="library-section"><div class="section-line library-heading"><div><span class="eyebrow muted">BIBLIOTECA PROFESIONAL</span><h2>Tu biblioteca de ejercicios<span class="coral-dot">.</span></h2><p class="small muted">Filtrá por región y tipo de trabajo. Solo en Rodilla → Fuerza aparecen los grupos musculares y sus variantes; las clasificaciones iniciales son sugeridas y editables.</p></div><div class="catalogue-actions">${btn('Ampliar biblioteca','open-catalogue','secondary','video')}${btn('Nuevo ejercicio','new-exercise','secondary','plus')}</div></div><div class="block-selector" aria-label="Filtrar por bloque">${['Todos',...blocks].map((x,i)=>`<button class="block-tile ${block===x||(!block&&x==='Todos')?'active':''}" data-action="filter-block" data-id="${x==='Todos'?'':x}"><span class="block-art block-art-${i}">${blockSymbol(x)}</span><span>${x}</span></button>`).join('')}</div><div class="toolbar library-toolbar"><label class="search"><span class="sr-only">Buscar ejercicio</span>${icon('search')}<input id="search" placeholder="¿Qué ejercicio estás buscando?" value="${esc(search)}"></label><select id="region-filter" aria-label="Región corporal"><option value="">Todas las regiones</option>${regions.map(x=>`<option ${region===x?'selected':''}>${x}</option>`).join('')}</select>${muscleFilters('library',libraryMuscle,libraryDominance)}<select id="library-family" aria-label="Grupo de variantes"><option value="">Todos los grupos</option>${exerciseFamilyNames().map(x=>`<option value="${esc(exerciseFamilyKey(x))}" ${libraryFamily===exerciseFamilyKey(x)?'selected':''}>${esc(x)}</option>`).join('')}</select><span id="result-count" class="results-count"></span></div><div id="exercise-results"></div></section>`);renderCards();$('#library-muscle').onchange=e=>{libraryMuscle=e.target.value;renderCards()};$('#library-dominance').onchange=e=>{libraryDominance=e.target.value;renderCards()};$('#search').oninput=e=>{search=e.target.value;renderCards()};$('#region-filter').onchange=e=>{region=e.target.value;renderCards()};$('#library-family').onchange=e=>{libraryFamily=e.target.value;renderCards()};document.querySelector('[data-action="scroll-library"]').onclick=()=>$('#library-section').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
function renderCards(){const scoped=syncSubgroupFilters('library',region,block);if(!scoped){libraryMuscle='';libraryDominance='';libraryFamily=''}const list=data.exercises.filter(e=>matchesMuscle(e,libraryMuscle,libraryDominance)&&matchesRegion(e,region)&&(!block||block===e.block)&&(!libraryFamily||exerciseFamilyKey(exerciseTags(e).family)===libraryFamily)&&norm((e.name||'')+' '+(e.notes||'')+' '+(exerciseTags(e).family||'')+' '+(e.relatedRegions||[]).join(' ')).includes(norm(search)));if(scoped)list.splice(0,list.length,...groupedExerciseList(list).flatMap(g=>g.items));$('#result-count').textContent=list.length+' ejercicios';$('#exercise-results').innerHTML=list.length?`${(scoped?groupedExerciseList(list):[{name:'',items:list}]).map(group=>`<section class="library-family-group">${scoped?`<h3 class="family-library-heading">${esc(group.name)}</h3>`:''}<div class="cards">${group.items.map((e,i)=>`<article class="exercise-card"><button style="padding:0;text-align:left;background:none" data-action="watch" data-id="${esc(e.id)}" aria-label="Ver ${esc(e.name)}">${imageCard(e,i)}</button><div class="card-body"><div class="card-meta">${esc(e.region)}<span>·</span>${esc(e.block)}</div><h3>${esc(e.name)}</h3>${catalogueReviewBadge(e)}${exerciseTagLabel(e)?`<p class="small muted">${esc(exerciseTagLabel(e))}</p>`:''}${exerciseTags(e).family?`<p class="family-card-tag">${esc(exerciseTags(e).family)}${e.familyOrder?' · Orden '+esc(e.familyOrder):''}</p>`:''}<p>${esc(e.notes||'Listo para personalizar en una rutina.')}</p><div class="card-actions"><button class="text-btn" data-action="assign" data-id="${esc(e.id)}">${icon('plus')} Agregar a rutina</button><button class="icon-btn" data-action="edit-exercise" data-id="${esc(e.id)}" aria-label="Editar ${esc(e.name)}">${icon('edit')}</button></div></div></article>`).join('')}</div></section>`).join('')}`:`<div class="empty">${icon('video')}<h3>${data.exercises.length?'No encontramos ejercicios':'Tu biblioteca empieza acá'}</h3><p>${data.exercises.length?'Probá con otro nombre, región o bloque.':'Agregá un video y reutilizalo en todas las rutinas que necesites.'}</p>${btn('Agregar ejercicio','new-exercise','','plus')}</div>`;bind($('#exercise-results'))}
function renderRoutines(){shell(`<div class="page-heading"><div><p class="eyebrow" style="margin:0 0 9px">PLANES QUE ACOMPAÑAN</p><h1>Rutinas individuales.</h1><p>Actualizá los ejercicios. El enlace sigue siendo el mismo.</p></div>${btn('Nueva rutina','new-routine','','plus')}</div><div class="toolbar"><label class="search">${icon('search')}<input id="routine-search" placeholder="Buscar paciente o referencia…" aria-label="Buscar rutina"></label></div><div id="routine-results"></div>`);renderRoutineRows('');$('#routine-search').oninput=e=>renderRoutineRows(e.target.value)}
function renderRoutineRows(q){const rs=data.routines.filter(r=>norm(r.label).includes(norm(q)));$('#routine-results').innerHTML=rs.length?`<div class="routine-list">${rs.map(r=>`<article class="routine-row"><span class="avatar">${esc(r.label.split(' ').filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase())}</span><div class="details"><h3>${esc(r.label)}</h3><p>${r.items.length} ejercicios · ${date(r.updated_at)}</p></div><span class="pill">${r.active?'Activa':'Pausada'}</span><div class="actions"><button class="btn secondary" data-action="edit-routine" data-id="${esc(r.id)}">${icon('edit')}Editar</button><button class="btn secondary" data-action="preview-routine" data-id="${esc(r.id)}">${icon('play')}Ver</button><button class="btn secondary" data-action="duplicate-routine" data-id="${esc(r.id)}">${icon('copy')}Duplicar</button><button class="btn" data-action="share-routine" data-id="${esc(r.id)}">${icon('link')}Enlace</button><button class="icon-btn" data-action="delete-routine" data-id="${esc(r.id)}" aria-label="Eliminar rutina de ${esc(r.label)}">${icon('trash')}</button></div></article>`).join('')}</div>`:`<div class="empty">${icon('users')}<h3>${q?'No hay coincidencias':'Cada persona, su propio plan'}</h3><p>Creá una rutina, seleccioná los ejercicios y ajustá las indicaciones para ese paciente.</p>${btn('Crear primera rutina','new-routine','','plus')}</div>`;bind($('#routine-results'))}
function newRoutine(exId){draft={id:uid(),label:'',token:uid()+uid().replaceAll('-',''),items:[],blockOrder:[...blocks],note:'',revision:0,active:true};if(exId)draft.items.push(newPlanItem(getExercise(exId)));dirty=true;current='editor';renderEditor()}
function renderEditor(){shell(`<div class="page-heading"><div><button class="text-btn" data-action="nav" data-id="routines">${icon('back')} Volver a mis rutinas</button><h1 style="margin-top:12px">${draft.revision?'Editar rutina':'Crear una rutina'}</h1><p>Seleccioná los ejercicios y completá las indicaciones individuales.</p></div><span id="dirty-label" class="unsaved">${dirty?'Cambios sin guardar':'Guardada'}</span></div><div class="editor-layout"><div><div class="panel"><label class="field">Nombre y apellido del paciente<input id="plan-label" maxlength="80" value="${esc(draft.label)}" placeholder="Ej. Martín González" autocomplete="off"><small>El paciente verá su nombre y apellido en la bienvenida.</small></label><label class="field" style="margin-bottom:0">Mensaje para el paciente<textarea id="plan-note" maxlength="1500" placeholder="Indicaciones generales para esta rutina…">${esc(draft.note)}</textarea></label></div><div class="section-line"><h2>Ejercicios de la rutina</h2>${btn('Seleccionar ejercicios','choose-exercises','secondary','plus')}</div><p class="order-hint">Para cambiar el orden, mantené apretada la mano y arrastrá. Mové un bloque completo o colocá cualquier ejercicio en la posición que quieras.</p><div id="plan-items">${renderPlanItems()}</div></div><aside class="panel sticky"><span class="eyebrow muted">TU PLAN, SIEMPRE AL DÍA</span><h3 style="margin-top:13px">${draft.items.length} ejercicios seleccionados</h3><p class="small muted">Los cambios se muestran al paciente cuando guardás la rutina y vuelve a abrir su enlace.</p><div class="divider"></div><div class="action-stack">${btn('Guardar cambios','save-routine','','check')}${btn('Vista del paciente','preview-draft','secondary','play')}${draft.revision?btn('Copiar enlace','share-draft','secondary','link'):''}${draft.revision?btn('Enviar por WhatsApp','whatsapp-draft','secondary','link'):''}${draft.revision?btn('Duplicar rutina','duplicate-draft','secondary','copy'):''}${draft.revision?btn('Ver y limpiar historial','history','ghost','clock'):''}${draft.revision?btn('Eliminar rutina','delete-draft','danger','trash'):''}</div><div class="divider"></div><label class="check-row" style="border:0;padding:0"><input type="checkbox" id="plan-active" ${draft.active?'checked':''}><span class="small">Rutina activa</span></label><p class="tiny muted" style="margin-top:9px">Si la pausás, el enlace deja de mostrar los ejercicios. Podés volver a activarla.</p>${demo?'<div class="notice warn" style="margin-top:20px">En esta prueba, guardar afecta solo a este navegador. El enlace para pacientes se habilita al conectar tu cuenta.</div>':''}</aside></div>`);$('#plan-label').oninput=e=>{draft.label=e.target.value;markDirty()};$('#plan-note').oninput=e=>{draft.note=e.target.value;markDirty()};$('#plan-active').onchange=e=>{draft.active=e.target.checked;markDirty()};$$('[data-dose]').forEach(el=>el.oninput=()=>{const item=draft.items[+el.dataset.index];item[el.dataset.dose]=el.value;markDirty()});$$('[data-order-block]').forEach(el=>el.onchange=()=>moveBlockToPosition(el.dataset.orderBlock,Number(el.value)));$$('[data-order-item]').forEach(el=>el.onchange=()=>moveItemToPosition(Number(el.dataset.orderItem),Number(el.value)));bindPlanDrag()}
function markDirty(){dirty=true;if($('#dirty-label'))$('#dirty-label').textContent='Cambios sin guardar'}
function moveBlockToPosition(name,target){const current=planBlocks(draft),from=current.indexOf(name);if(from<0||target<0||target>=current.length||from===target)return;const destination=current[target],moving=draft.items.filter(x=>x.exercise.block===name),remaining=draft.items.filter(x=>x.exercise.block!==name);let insert;if(target<from)insert=remaining.findIndex(x=>x.exercise.block===destination);else{insert=remaining.length;for(let i=remaining.length-1;i>=0;i--)if(remaining[i].exercise.block===destination){insert=i+1;break}}remaining.splice(insert,0,...moving);draft.items=remaining;markDirty();renderEditor()}
function moveItemToPosition(index,target){if(!Number.isInteger(index)||!Number.isInteger(target)||index<0||target<0||index>=draft.items.length||target>=draft.items.length||index===target)return;draft.items.splice(target,0,draft.items.splice(index,1)[0]);markDirty();renderEditor()}
function renderPlanItems(){if(!draft.items.length)return `<div class="empty">${icon('grid')}<h3>Elegí los ejercicios de este plan</h3><p>Una tilde agrega el ejercicio con sus valores habituales. Después podés ajustarlos.</p>${btn('Abrir biblioteca','choose-exercises','','plus')}</div>`;const bs=planBlocks(draft),items=orderedItems(draft);return `<div class="block-reorder-list"><h3>Ordenar bloques completos</h3><p class="small muted">Al mover un bloque, sus ejercicios se reúnen y se trasladan juntos.</p>${bs.map((b,bi)=>`<div class="plan-block block-order-head" data-drag-block="${esc(b)}"><button type="button" class="drag-handle" data-drag-handle="block" data-drag-value="${esc(b)}" aria-label="Arrastrar bloque ${esc(b)}">${icon('hand')}<span>Arrastrar bloque</span></button><h3 class="block-heading">${esc(b)}</h3><div class="order-controls"><label>Orden <select data-order-block="${esc(b)}" aria-label="Orden del bloque ${esc(b)}">${bs.map((_,position)=>`<option value="${position}" ${position===bi?'selected':''}>${position+1}</option>`).join('')}</select></label><button class="icon-btn" data-action="block-up" data-id="${esc(b)}" aria-label="Subir bloque ${esc(b)}" ${bi===0?'disabled':''}>${icon('up')}</button><button class="icon-btn" data-action="block-down" data-id="${esc(b)}" aria-label="Bajar bloque ${esc(b)}" ${bi===bs.length-1?'disabled':''}>${icon('down')}</button></div></div>`).join('')}</div><h3 class="free-order-heading">Orden de los ejercicios</h3>${items.map((x,i)=>`<article class="plan-item" data-drag-item="${i}" data-item-block="${esc(x.exercise.block)}"><div class="plan-item-head"><button type="button" class="drag-handle item-drag-handle" data-drag-handle="item" data-drag-value="${i}" aria-label="Arrastrar ejercicio ${esc(x.exercise.name)}">${icon('hand')}<span>Arrastrar</span></button><span class="number">${i+1}</span><h3>${esc(x.exercise.name)}<small class="item-block-badge">${esc(x.exercise.block)}</small></h3><label class="item-order-label">Posición <select data-order-item="${i}" aria-label="Posición de ${esc(x.exercise.name)}">${items.map((_,position)=>`<option value="${position}" ${position===i?'selected':''}>${position+1}</option>`).join('')}</select></label><button class="icon-btn" data-action="move-up" data-id="${i}" aria-label="Subir ejercicio ${esc(x.exercise.name)}" ${i===0?'disabled':''}>${icon('up')}</button><button class="icon-btn" data-action="move-down" data-id="${i}" aria-label="Bajar ejercicio ${esc(x.exercise.name)}" ${i===items.length-1?'disabled':''}>${icon('down')}</button><button class="btn danger remove-plan-exercise" data-action="remove-item" data-id="${i}" aria-label="Quitar ejercicio ${esc(x.exercise.name)}">${icon('trash')} Quitar de esta rutina</button></div><div class="grid3">${doseFields.map(([k,label,ph])=>`<label class="field">${label}<input maxlength="80" data-dose="${k}" data-index="${i}" placeholder="${ph}" value="${esc(x[k])}"></label>`).join('')}</div><label class="field" style="margin-bottom:0">Indicación individual (opcional)<input maxlength="500" data-dose="notes" data-index="${i}" value="${esc(x.notes)}" placeholder="Una aclaración para este paciente…"></label>${getExercise(x.exercise.id)?`<button class="text-btn item-refresh" data-action="refresh-item" data-id="${i}">${icon('video')}Actualizar video e indicaciones desde la biblioteca</button>`:''}</article>`).join('')}`}
function bindPlanDrag(){const container=$('#plan-items');if(!container)return;container.querySelectorAll('[data-drag-handle]').forEach(handle=>{handle.addEventListener('pointerdown',event=>{if(event.button!==0)return;event.preventDefault();const kind=handle.dataset.dragHandle,value=handle.dataset.dragValue,source=kind==='block'?handle.closest('[data-drag-block]'):handle.closest('[data-drag-item]');let target=null,lastY=event.clientY,lastX=event.clientX,raf=0,moved=false;handle.setPointerCapture(event.pointerId);source.classList.add('drag-source');const setTarget=()=>{const node=document.elementFromPoint(lastX,lastY);let candidate=kind==='block'?node?.closest('[data-drag-block]'):node?.closest('[data-drag-item]');if(target!==candidate){target?.classList.remove('drag-target');target=candidate;target?.classList.add('drag-target')}};const tick=()=>{if(lastY<75)window.scrollBy(0,-13);else if(lastY>window.innerHeight-75)window.scrollBy(0,13);setTarget();raf=requestAnimationFrame(tick)};const move=e=>{lastX=e.clientX;lastY=e.clientY;moved=true;setTarget()};const finish=e=>{cancelAnimationFrame(raf);handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',finish);handle.removeEventListener('pointercancel',cancel);source.classList.remove('drag-source');target?.classList.remove('drag-target');if(e.type==='pointercancel'||!moved||!target||target===source)return;if(kind==='block'){const destination=planBlocks(draft).indexOf(target.dataset.dragBlock);moveBlockToPosition(value,destination)}else{const destinationIndex=Number(target.dataset.dragItem);moveItemToPosition(Number(value),destinationIndex)}};const cancel=e=>finish(e);handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',cancel);raf=requestAnimationFrame(tick)})})}
function modal(title,body,wide=false){dialog.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Cerrar">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;dialog.style.maxWidth=wide?'850px':'720px';if(!dialog.open)dialog.showModal();bind(dialog)}
dialog.addEventListener('cancel',()=>stopMedia(dialog));
dialog.addEventListener('close',()=>{stopMedia(dialog);if(dialog.querySelector('.patient-video-large'))dialog.innerHTML=''});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal()}});
function closeModal(){stopMedia(dialog);dialog.close();if(pendingURL){URL.revokeObjectURL(pendingURL);pendingURL=null}pendingFile=null}
function exerciseFamilyKey(value){return norm(String(value||'').trim().replace(/\s+/g,' '))}
function exerciseFamilyNames(){const names=new Map();data.exercises.forEach(e=>{const name=String(exerciseTags(e).family||'').trim().replace(/\s+/g,' '),key=exerciseFamilyKey(name);if(key&&!names.has(key))names.set(key,name)});return [...names.values()].sort((a,b)=>a.localeCompare(b,'es'))}
function groupedExerciseList(list){const groups=new Map();list.forEach(e=>{const key=exerciseFamilyKey(exerciseTags(e).family);if(!groups.has(key))groups.set(key,{name:key?exerciseTags(e).family:'Sin grupo',items:[]});groups.get(key).items.push(e)});return [...groups.entries()].sort(([a],[b])=>!a?1:!b?-1:a.localeCompare(b,'es')).map(([,g])=>({...g,items:g.items.sort((a,b)=>{const av=Number(a.familyOrder)||Infinity,bv=Number(b.familyOrder)||Infinity;return av-bv||String(a.name||'').localeCompare(String(b.name||''),'es')})}))}
function matchesExerciseFilters(e,query,selectedRegion,selectedBlock){return matchesRegion(e,selectedRegion)&&(!selectedBlock||e.block===selectedBlock)&&norm((e.name||'')+' '+(e.block||'')+' '+(exerciseTags(e).family||'')).includes(norm(query))}
function chooseExercises(){const selected=new Set(draft.items.map(x=>x.exercise.id));modal('Seleccionar ejercicios',`<p class="small muted" style="margin-bottom:18px">Cada tilde agrega el ejercicio a esta rutina con sus valores habituales. Los cambios se publican cuando guardás.</p><div class="toolbar"><label class="search">${icon('search')}<input id="choose-search" placeholder="Buscar ejercicio…" aria-label="Buscar ejercicio"></label><select id="choose-region" aria-label="Región"><option value="">Todas las regiones</option>${regions.map(x=>`<option>${x}</option>`).join('')}</select>${muscleFilters('choose')}<select id="choose-family" aria-label="Grupo de ejercicios"><option value="">Todos los grupos</option>${exerciseFamilyNames().map(x=>`<option value="${esc(exerciseFamilyKey(x))}">${esc(x)}</option>`).join('')}</select><select id="choose-block" aria-label="Tipo de trabajo"><option value="">Todos los tipos de trabajo</option>${blocks.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="chooser-list" id="chooser"></div><div class="dialog-footer"><span id="chosen-count" class="selection-count" style="margin-right:auto;align-self:center"></span>${btn('Volver a la rutina','finish-selection','','check')}</div>`);const draw=()=>{const q=$('#choose-search').value,reg=$('#choose-region').value,chosenBlock=$('#choose-block').value;const scoped=syncSubgroupFilters('choose',reg,chosenBlock),family=$('#choose-family').value;const matching=data.exercises.filter(e=>matchesExerciseFilters(e,q,reg,chosenBlock)&&matchesMuscle(e,$('#choose-muscle').value,$('#choose-dominance').value)&&(!family||exerciseFamilyKey(exerciseTags(e).family)===family));$('#chooser').innerHTML=(scoped?groupedExerciseList(matching):[{name:'',items:matching}]).map(group=>`<section class="family-choice-group">${scoped?`<h3>${esc(group.name)}</h3>`:''}${group.items.map(e=>`<div class="chooser-exercise"><label class="check-row chooser-check"><input type="checkbox" value="${esc(e.id)}" ${selected.has(e.id)?'checked':''}><span>${esc(e.name)}<small>${esc(e.region)} · ${esc(e.block)}${exerciseTagLabel(e)?' · '+esc(exerciseTagLabel(e)):''}${e.familyOrder?' · Orden '+esc(e.familyOrder):''}${e.url?'':' · Ejemplo sin video'}</small>${e.catalogueId&&e.reviewStatus!=='clinician_reviewed'?'<small>Fuente comprobada · revisión visual pendiente</small>':''}</span></label><button type="button" class="chooser-preview" data-preview-exercise="${esc(e.id)}" aria-label="Ver video de ${esc(e.name)}">${youtubeId(e.url)?`<img src="https://i.ytimg.com/vi/${youtubeId(e.url)}/mqdefault.jpg" alt="" loading="lazy">`:icon('video')}<span>${icon('play')} Ver video</span></button></div>`).join('')}</section>`).join('')||'<p class="muted small">No hay ejercicios para esta búsqueda.</p>';$$('#chooser input').forEach(el=>el.onchange=()=>{if(el.checked){selected.add(el.value);if(!draft.items.some(x=>x.exercise.id===el.value))draft.items.push(newPlanItem(getExercise(el.value)))}else{selected.delete(el.value);draft.items=draft.items.filter(x=>x.exercise.id!==el.value)}markDirty();count()});$$('#chooser [data-preview-exercise]').forEach(el=>el.onclick=()=>previewChooserExercise(el.dataset.previewExercise));count()};const count=()=>$('#chosen-count').textContent=selected.size+' seleccionados';$('#choose-muscle').onchange=draw;$('#choose-dominance').onchange=draw;$('#choose-search').oninput=draw;$('#choose-region').onchange=draw;$('#choose-block').onchange=draw;$('#choose-family').onchange=draw;draw();dialog.querySelector('[data-action="finish-selection"]').onclick=closeModal;dialog.addEventListener('close',()=>{if(current==='editor')renderEditor()},{once:true})}
function previewChooserExercise(id){const e=getExercise(id);if(!e)return;const overlay=document.createElement('dialog');overlay.className='chooser-video-dialog';overlay.setAttribute('aria-label','Video de '+e.name);overlay.innerHTML=`<div class="dialog-head"><h2>${esc(e.name)}</h2><button type="button" class="icon-btn" aria-label="Cerrar video">${icon('close')}</button></div><div class="dialog-body"><div class="media-wrap">${mediaHTML(e)}</div><button type="button" class="btn secondary chooser-video-close">Cerrar video y volver a la selección</button></div>`;document.body.appendChild(overlay);const cleanup=()=>{stopMedia(overlay);overlay.remove()};overlay.addEventListener('close',cleanup,{once:true});overlay.querySelectorAll('button').forEach(b=>b.onclick=()=>overlay.close());overlay.showModal();bindVideos(overlay)}
function mediaHTML(e){if(!e.url)return `<div class="demo-video-visual">${illustration(e.art||0)}<span class="demo-video-label">Imagen de referencia · agregá el video del ejercicio</span></div>`;const yt=youtubeId(e.url);if(yt)return `<iframe class="media" title="${esc(e.name)}" src="https://www.youtube-nocookie.com/embed/${yt}?rel=0&playsinline=1&start=${Math.floor(e.start||0)}${e.end?'&end='+Math.floor(e.end):''}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe><p class="tiny muted">Si el video no se reproduce, <a href="https://www.youtube.com/watch?v=${yt}&t=${Math.floor(e.start||0)}s" target="_blank" rel="noopener noreferrer">abrilo en YouTube</a>.</p>`;if(!safeUrl(e.url)&&!e.url.startsWith('blob:'))return '<p class="error-text">El enlace de video no es válido.</p>';return `<video class="media" controls playsinline preload="metadata" src="${esc(e.url)}" data-start="${Number(e.start)||0}" data-end="${Number(e.end)||0}"></video><p class="tiny muted">${e.start||e.end?'Se muestra el fragmento seleccionado. ':''}<a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Abrir video original</a></p>`}
function bindVideos(root=document){root.querySelectorAll('video[data-start]').forEach(v=>{const start=+v.dataset.start,end=+v.dataset.end;let guarding=false;v.onloadedmetadata=()=>{if(start>=v.duration){v.insertAdjacentHTML('afterend','<p class="error-text">El comienzo del fragmento supera la duración del video. Consultá con Tomás.</p>');return}if(start)v.currentTime=start};v.onplay=()=>{if((end&&v.currentTime>=end)||v.currentTime<start)v.currentTime=start};v.onseeked=()=>{if(guarding)return;if(v.currentTime<start||end&&v.currentTime>end){guarding=true;v.currentTime=start;setTimeout(()=>guarding=false,100)}};v.ontimeupdate=()=>{if(end&&v.currentTime>=end){v.pause();v.currentTime=start}};v.onerror=()=>{if(!v.nextElementSibling?.classList.contains('media-error'))v.insertAdjacentHTML('afterend','<p class="error-text media-error">No se pudo cargar este video. El sitio de origen puede impedir su reproducción. Probá el enlace original o consultá con Tomás.</p>')}})}
function stopMedia(root){root.querySelectorAll('video').forEach(v=>v.pause());root.querySelectorAll('iframe').forEach(f=>f.src='about:blank')}
function watch(id){const e=getExercise(id);modal(esc(e.name),`<div class="card-meta">${esc(e.region)} · ${esc(e.block)}</div><div class="media-wrap">${mediaHTML(e)}</div><p class="small muted">${esc(e.notes)}</p>${e.start||e.end?`<p class="tiny muted" style="margin-top:12px">Fragmento: ${e.start||0} s ${e.end?'a '+e.end+' s':'hasta el final'}.</p>`:''}<div class="dialog-footer">${btn('Editar ejercicio','edit-exercise','secondary','edit').replace('data-action="edit-exercise"',`data-action="edit-exercise" data-id="${esc(id)}"`)}</div>`);bindVideos(dialog)}
function exerciseForm(id){if(dialog.open)closeModal();const e=id?getExercise(id):{name:'',region:'Rodilla',block:'Movilidad',source:'youtube',url:'',start:0,end:null,notes:''};modal(id?'Editar ejercicio':'Nuevo ejercicio',`<form id="exercise-form"><div id="exercise-error" class="error-text" role="alert"></div>${e.catalogueId?`<div class="notice catalogue-review-note"><p>${esc(e.reviewNote||'Revisá el video antes de asignar esta incorporación.')}</p><p>Fuente: ${esc(e.author)}${safeUrl(e.sourcePage)?` · <a href="${esc(e.sourcePage)}" target="_blank" rel="noopener noreferrer">Ver fuente</a>`:''}</p><label class="catalogue-reviewed-check"><input name="clinicianReviewed" type="checkbox" ${e.reviewStatus==='clinician_reviewed'?'checked':''}> Ya revisé la ejecución y el fragmento de este video.</label></div>`:''}<label class="field">Nombre del ejercicio (opcional)<input name="name" maxlength="120" value="${esc(e.name)}" placeholder="Ej. Extensión de rodilla sentado"></label><div class="grid2"><label class="field">Región corporal<select name="region">${regions.map(x=>`<option ${e.region===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Bloque<select name="block">${blocks.map(x=>`<option ${e.block===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="family-editor"><h3>Grupo muscular y movimiento</h3><p class="small muted">Podés marcar más de un grupo. La clasificación organiza tu biblioteca y no modifica las rutinas existentes.</p><div class="grid2"><fieldset class="muscle-checks"><legend>Grupo muscular</legend>${muscleGroupNames.map(x=>`<label><input type="checkbox" name="muscleGroups" value="${esc(x)}" ${exerciseTags(e).muscleGroups.includes(x)?'checked':''}> ${esc(x)}</label>`).join('')}</fieldset><label class="field">Dominante del movimiento<select name="dominance"><option value="">Sin clasificar / no corresponde</option>${['Cadera','Rodilla'].map(x=>`<option value="${x}" ${exerciseTags(e).dominance===x?'selected':''}>Dominante de ${x.toLowerCase()}</option>`).join('')}</select><small>La carga, el rango y la ejecución siguen definiéndose para cada paciente.</small></label></div></div><div class="family-editor"><h3>Grupo de variantes (opcional)</h3><p class="small muted">Agrupá ejercicios similares, por ejemplo “Puente de glúteos”. El orden lo definís vos y podés modificarlo.</p><div class="grid2"><label class="field">Nombre del grupo<input name="family" list="exercise-families" maxlength="100" value="${esc(exerciseTags(e).family||'')}" placeholder="Ej. Puente de glúteos"><datalist id="exercise-families">${exerciseFamilyNames().map(x=>`<option value="${esc(x)}">`).join('')}</datalist><small>Escribí un grupo nuevo o elegí uno existente.</small></label><label class="field">Orden dentro del grupo<input name="familyOrder" type="number" min="1" max="9999" step="1" value="${esc(e.familyOrder||'')}" placeholder="Ej. 1"><small>Opcional: 1, 2, 3… según tu criterio.</small></label></div></div><label class="field">Origen del video<select id="video-source" name="source"><option value="youtube" ${e.source==='youtube'?'selected':''}>Enlace de YouTube</option><option value="external" ${e.source==='external'?'selected':''}>Enlace directo a un video (MP4 / WebM)</option><option value="file" ${e.source==='file'?'selected':''}>Subir desde mi computadora o celular</option></select></label><div id="url-field"><label class="field">Enlace del video<input type="url" name="url" id="video-url" value="${esc(e.url)}" placeholder="https://www.youtube.com/watch?v=…"><small>Para un artículo, necesitás el enlace directo al archivo de video, no a la página del artículo.</small></label></div><div id="file-field" class="file-area" style="display:none;margin-bottom:16px"><label class="field">Archivo de video<input id="video-file" type="file" accept="video/mp4,video/webm,video/quicktime"><small>Máximo 50 MB por archivo. MP4 con video H.264 es la opción más compatible con celulares.${demo?' En modo prueba el archivo solo se puede previsualizar; no se sube.':''}</small></label>${e.url?'<p class="tiny muted">Ya hay un video guardado. Elegí otro solo si querés reemplazarlo.</p>':''}</div><div class="toolbar">${btn('Previsualizar video','preview-video','secondary','play')}</div><div id="video-preview"></div><div class="grid2"><label class="field">Mostrar desde (segundos)<input type="number" name="start" min="0" step="0.1" value="${e.start||0}"></label><label class="field">Mostrar hasta (segundos)<input type="number" name="end" min="0.1" step="0.1" value="${e.end||''}" placeholder="Hasta el final"></label></div><p class="tiny muted" style="margin-bottom:17px">Selecciona el fragmento que se reproduce. El archivo original se conserva completo; esto no reduce su tamaño.</p><label class="field">Indicaciones generales<textarea name="notes" maxlength="1500" placeholder="Cómo realizarlo y qué tener en cuenta…">${esc(e.notes)}</textarea><small>Podés agregar una indicación general y ajustar los valores para cada paciente.</small></label><h3 class="defaults-title">Valores habituales (opcionales)</h3><p class="small muted" style="margin-bottom:15px">Se copian al seleccionar este ejercicio y después podés cambiarlos para cada paciente.</p><div class="grid3">${doseFields.map(([k,l,ph])=>`<label class="field">${l}<input name="default_${k}" maxlength="80" placeholder="${ph}" value="${esc(e.defaults?.[k]||'')}"></label>`).join('')}</div><div class="dialog-footer">${id?`<button type="button" class="btn danger" data-action="delete-exercise" data-id="${esc(id)}" style="margin-right:auto">${icon('trash')}Eliminar</button>`:''}<button type="button" class="btn secondary" data-action="close">Cancelar</button><button type="submit" class="btn" id="exercise-submit">${icon('check')}Guardar ejercicio</button></div></form>`);const f=$('#exercise-form');const invalidateVideoReview=ev=>{if(['url','source','start','end'].includes(ev.target.name)&&f.elements.clinicianReviewed)f.elements.clinicianReviewed.checked=false};f.addEventListener('input',invalidateVideoReview);f.addEventListener('change',invalidateVideoReview);const updateSubgroups=()=>{const active=isKneeStrength({region:f.elements.region.value,block:f.elements.block.value});f.querySelectorAll('.family-editor').forEach(el=>{el.hidden=!active})};f.elements.region.onchange=updateSubgroups;f.elements.block.onchange=updateSubgroups;updateSubgroups();const updateSource=()=>{const file=$('#video-source').value==='file';$('#url-field').style.display=file?'none':'block';$('#file-field').style.display=file?'block':'none';$('#video-url').required=!file};$('#video-source').onchange=updateSource;updateSource();$('#video-file').onchange=()=>{pendingFile=$('#video-file').files[0]||null;if(pendingURL)URL.revokeObjectURL(pendingURL);pendingURL=pendingFile?URL.createObjectURL(pendingFile):null};dialog.querySelector('[data-action="preview-video"]').onclick=ev=>{ev.preventDefault();const v=Object.fromEntries(new FormData(f));v.url=v.source==='file'?(pendingURL||e.url):v.url;v.name=v.name||'Vista previa';v.start=+v.start||0;v.end=+v.end||null;if(!v.url){toast('Elegí un video o pegá su enlace.');return}$('#video-preview').innerHTML=`<div class="media-wrap">${mediaHTML(v)}</div>`;bindVideos($('#video-preview'))};f.onsubmit=async ev=>{ev.preventDefault();const b=$('#exercise-submit');b.disabled=true;$('#exercise-error').textContent='';try{const v={...e,...Object.fromEntries(new FormData(f))};if(e.catalogueId)applyCatalogueReview(e,v,new FormData(f).has('clinicianReviewed'));delete v.clinicianReviewed;v.taxonomyVersion=1;v.muscleGroups=new FormData(f).getAll('muscleGroups').filter(x=>muscleGroupNames.includes(x));v.dominance=['Cadera','Rodilla'].includes(v.dominance)?v.dominance:'';v.name=v.name.trim()||'Ejercicio '+(data.exercises.length+1);v.family=String(v.family||'').trim().replace(/\s+/g,' ');const existingFamily=exerciseFamilyNames().find(x=>exerciseFamilyKey(x)===exerciseFamilyKey(v.family));if(existingFamily)v.family=existingFamily;v.familyOrder=v.family&&v.familyOrder?Number(v.familyOrder):null;if(v.familyOrder!==null&&(!Number.isInteger(v.familyOrder)||v.familyOrder<1||v.familyOrder>9999))throw Error('El orden del grupo debe ser un número entre 1 y 9999.');if(!isKneeStrength(v)&&id){v.muscleGroups=Array.isArray(e.muscleGroups)?e.muscleGroups:[];v.dominance=e.dominance||'';v.family=e.family||'';v.familyOrder=e.familyOrder||null}v.defaults=Object.fromEntries(doseFields.map(([k])=>[k,String(v['default_'+k]||'').trim()]));doseFields.forEach(([k])=>delete v['default_'+k]);v.start=Number(v.start)||0;v.end=v.end?Number(v.end):null;if(!Number.isFinite(v.start)||v.start<0||v.end!==null&&(!Number.isFinite(v.end)||v.end<0))throw Error('Revisá los segundos del fragmento.');if(v.end&&v.end<=v.start)throw Error('El final del fragmento debe ser posterior al comienzo.');if(v.source==='file'){if(pendingFile){if(demo)throw Error('Para guardar archivos propios primero conectá tu cuenta. Podés probar con un enlace de YouTube.');if(pendingFile.size>50*1024*1024)throw Error('El archivo supera los 50 MB. Recortalo o subilo a YouTube como no listado.');if(!['video/mp4','video/webm','video/quicktime'].includes(pendingFile.type))throw Error('Usá un archivo MP4, WebM o MOV.');const ext={'video/mp4':'mp4','video/webm':'webm','video/quicktime':'mov'}[pendingFile.type];const path=uid()+'.'+ext;await api('/storage/v1/object/exercise-videos/'+path,{method:'POST',headers:{'Content-Type':pendingFile.type,'x-upsert':'false'},body:pendingFile});v.url=config.supabaseUrl+'/storage/v1/object/public/exercise-videos/'+path}else if(!e.url||e.source!=='file')throw Error('Seleccioná un archivo de video para subir.');else v.url=e.url}else if(!safeUrl(v.url))throw Error('Pegá un enlace HTTPS válido.');if(v.source==='youtube'&&!youtubeId(v.url))throw Error('No reconocemos este enlace de YouTube. Revisá que sea el enlace de un video.');v.id=id||uid();if(!demo){await api('/rest/v1/exercises?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body:JSON.stringify({id:v.id,content:v})});await loadData()}else{const idx=data.exercises.findIndex(x=>x.id===id);if(idx>=0)data.exercises[idx]=v;else data.exercises.unshift(v);storeDemo()}closeModal();current='library';renderLibrary();toast('Ejercicio guardado. Las rutinas existentes conservan su versión hasta que las actualices.')}catch(err){$('#exercise-error').textContent=err.message;b.disabled=false}}}
async function deleteExercise(id){if(!await confirmDialog('¿Eliminar este ejercicio?','Se quitará de la biblioteca. Las rutinas ya guardadas conservan su video e indicaciones.'))return;try{if(!demo)await api('/rest/v1/exercises?id=eq.'+encodeURIComponent(id),{method:'DELETE'});data.exercises=data.exercises.filter(e=>e.id!==id);if(demo)storeDemo();closeModal();renderLibrary();toast('Ejercicio eliminado de la biblioteca.')}catch(e){toast(e.message)}}
function confirmDialog(title,body){return new Promise(resolve=>{let settled=false;const done=v=>{if(settled)return;settled=true;resolve(v)};modal(title,`<p class="small muted">${body}</p><div class="dialog-footer"><button class="btn secondary" id="confirm-no">Cancelar</button><button class="btn" id="confirm-yes">Continuar</button></div>`);$('#confirm-no').onclick=()=>{closeModal();done(false)};$('#confirm-yes').onclick=()=>{done(true);closeModal()};dialog.addEventListener('close',()=>done(false),{once:true})})}
async function saveRoutine(){if(saveBusy)return;if(!draft.label.trim()){toast('Agregá el nombre y apellido del paciente.');$('#plan-label').focus();return}if(!draft.items.length){toast('Seleccioná al menos un ejercicio.');return}const invalidVideo=!demo&&draft.items.find(x=>!/^https:\/\//i.test(x.exercise.url||''));if(invalidVideo){toast('Revisá el video de «'+(invalidVideo.exercise.name||'ejercicio sin nombre')+'»: necesita un enlace HTTPS válido.');return}if(data.routines.some(r=>r.id!==draft.id&&normalizeName(r.label)===normalizeName(draft.label))){toast('Ya existe una rutina para este nombre. Editá esa rutina para mantener su enlace.');return}saveBusy=true;const rollbackDraft=structuredClone(draft),rollbackData=structuredClone(data);draft.items=orderedItems(draft);$$('[data-action="save-routine"]').forEach(b=>b.disabled=true);app.inert=true;let reloadFailed=false;try{draft.label=draft.label.trim().replace(/\s+/g,' ');const previous=data.routines.find(r=>r.id===draft.id);if(previous&&JSON.stringify([previous.label,previous.items,previous.note,previous.active])===JSON.stringify([draft.label,draft.items,draft.note,draft.active])){dirty=false;renderEditor();toast('No hay cambios nuevos para guardar.');return}if(demo){const prev=data.routines.find(x=>x.id===draft.id);const history=prev?{updated_at:prev.updated_at,items:prev.items,note:prev.note,label:prev.label,revision:prev.revision}:null;draft={...draft,revision:draft.revision+1,updated_at:new Date().toISOString(),history:[...(prev?.history||[]),...(history?[history]:[])]};const idx=data.routines.findIndex(x=>x.id===draft.id);if(idx>=0)data.routines[idx]=structuredClone(draft);else data.routines.unshift(structuredClone(draft));storeDemo()}else{const result=await api('/rest/v1/rpc/save_routine',{method:'POST',body:JSON.stringify({p_id:draft.id,p_label:draft.label,p_token:draft.token,p_items:draft.items,p_note:draft.note,p_active:draft.active,p_expected_revision:draft.revision})});draft={...draft,...result};const saved=structuredClone(draft),idx=data.routines.findIndex(r=>r.id===draft.id);if(idx>=0)data.routines[idx]=saved;else data.routines.unshift(saved);try{await loadData()}catch{reloadFailed=true}}dirty=false;renderEditor();toast(reloadFailed?'Rutina guardada. No se pudo actualizar la lista; revisá tu conexión.':demo?'Prueba guardada en este navegador.':'Rutina actualizada. El enlace sigue siendo el mismo.')}catch(e){if(demo){draft=rollbackDraft;data=rollbackData;dirty=true}toast(e.message.includes('CONFLICT')?'La rutina cambió en otro dispositivo. Volvé a abrirla antes de guardar.':e.message.includes('plan_unique_patient_name')?'Ya existe una rutina para este nombre y apellido. Editá la existente.':e.message)}finally{saveBusy=false;app.inert=false;$$('[data-action="save-routine"]').forEach(b=>b.disabled=false)}}
async function copyText(t){try{await navigator.clipboard.writeText(t);toast('Enlace copiado. Ya podés pegarlo en WhatsApp.')}catch{modal('Copiar enlace',`<p class="small muted">Seleccioná el enlace y copialo.</p><textarea readonly style="width:100%;margin-top:15px">${esc(t)}</textarea>`);dialog.querySelector('textarea').select()}}
function routineURL(r){const u=new URL(location.href);u.search='';u.hash='';u.searchParams.set('p',r.token);return u.href}
function share(r){if(demo){toast('Los enlaces se habilitan al conectar tu cuenta. Esta prueba solo está en tu navegador.');return}if(!r.active){toast('Activá y guardá la rutina antes de compartir el enlace.');return}if(dirty&&draft?.id===r.id){toast('Guardá los cambios antes de copiar el enlace.');return}copyText(routineURL(r))}
async function showHistory(){try{const h=demo?[...(data.routines.find(r=>r.id===draft.id)?.history||[])].reverse():await api('/rest/v1/routine_history?routine_id=eq.'+draft.id+'&select=revision,label,note,items,created_at&order=revision.desc');modal('Historial de la rutina',`<p class="small muted" style="margin-bottom:15px">Solo vos ves las versiones anteriores. Borrarlas conserva la rutina actual y su enlace. No hay copias adicionales de los videos.</p>${h.length?`<div class="history-tools">${btn('Borrar historial y conservar la actual','clear-history','danger','trash')}</div>`+h.map(x=>`<div class="history-entry"><div class="history-version"><strong class="small">Versión ${x.revision} · ${date(x.created_at||x.updated_at)}</strong><button class="icon-btn" data-action="delete-history-version" data-id="${x.revision}" aria-label="Eliminar versión ${x.revision}">${icon('trash')}</button></div><p>${x.items.map(y=>esc(y.exercise.name)+': '+esc(y.series||'—')+' series × '+esc(y.reps||'—')).join('<br>')}</p>${x.note?`<p>${esc(x.note)}</p>`:''}</div>`).join(''):'<div class="notice">Todavía no hay versiones anteriores.</div>'}`)}catch(e){toast(e.message)}}
function patientView(r,isPreview=false){stopMedia(document);const grouped=planBlocks(r),items=orderedItems(r),segments=planSegments(items);preview=isPreview;app.innerHTML=`${isPreview?`<div class="preview-label">Vista del paciente ${dirty?'· cambios todavía sin guardar':''} <button class="text-btn" data-action="back-editor" style="display:inline-flex;margin-left:15px">${icon('back')} Volver al panel</button></div>`:''}<main id="main" class="patient-shell patient-compact"><header class="patient-top">${brand()}<span class="status"><span class="dot"></span>Tu plan de ejercicios</span></header><section class="patient-welcome"><div><span class="eyebrow">BIENVENIDO</span><h1>${esc(r.label||'Nombre y apellido')}</h1><p>Esta va a ser la rutina que tenés que hacer en tu casa.</p></div><img src="assets/movement-hero.webp" alt="Hombre y mujer haciendo ejercicio" class="welcome-art"><div class="patient-summary"><span>${r.items.length} ejercicios</span><span>${grouped.length} bloques</span><span>Actualizado ${date(r.updated_at||new Date())}</span></div></section>${r.note?`<div class="notice patient-general-note" style="white-space:pre-wrap">${esc(r.note)}</div>`:''}${demo?'<div class="demo-banner patient-demo">Vista de prueba. Estas indicaciones son ejemplos para revisar la página.</div>':''}<p class="routine-table-hint">Tocá la miniatura para ampliar el video. Cerralo para volver a la tabla.</p><nav class="chip-row" aria-label="Bloques de tu rutina">${grouped.map(b=>`<a class="chip" href="#block-${blocks.indexOf(b)}-${segments.findIndex(segment=>segment.name===b)}">${esc(b)}</a>`).join('')}</nav>${segments.map((segment,segmentIndex)=>{const b=segment.name;return `<section class="patient-block" id="block-${blocks.indexOf(b)}-${segmentIndex}" aria-label="Ejercicios de ${esc(b)}"><h2><span class="patient-block-symbol">${blockSymbol(b)}</span><span>${esc(b)}<small>TIPO DE TRABAJO</small></span></h2><div class="routine-table-wrap"><table class="routine-table"><caption class="sr-only">Ejercicios e indicaciones de ${esc(b)}</caption><thead><tr><th scope="col">Ejercicio</th>${doseFields.map(([,label])=>`<th scope="col">${esc(label)}</th>`).join('')}<th scope="col">Video</th></tr></thead><tbody>${segment.items.map(x=>`<tr><th scope="row" class="routine-name"><span class="routine-number">${String(items.indexOf(x)+1).padStart(2,'0')}</span><span>${esc(x.exercise.name)}${x.exercise.notes||x.notes?`<small class="routine-row-notes">${esc([x.exercise.notes,x.notes].filter(Boolean).join(' · '))}</small>`:''}</span></th>${doseFields.map(([k,label])=>`<td data-label="${esc(label)}">${esc(x[k]||'—')}</td>`).join('')}<td class="routine-video-cell"><button class="routine-video-thumb" type="button" data-patient-video="${items.indexOf(x)}" aria-label="Ampliar video de ${esc(x.exercise.name)}">${youtubeId(x.exercise.url)?`<img src="https://i.ytimg.com/vi/${youtubeId(x.exercise.url)}/mqdefault.jpg" alt="" loading="lazy">`:x.exercise.source!=='youtube'&&safeUrl(x.exercise.url)?`<video src="${esc(x.exercise.url)}#t=${Number(x.exercise.start)||0.1}" preload="metadata" muted playsinline aria-hidden="true" tabindex="-1"></video>`:icon('video')}<span>${icon('play')}<span>Ver video</span></span></button></td></tr>`).join('')}</tbody></table></div></section>`}).join('')}<footer class="patient-footer"><img src="logo.svg" alt="" width="37" height="37" style="margin-bottom:12px"><strong>Tomás Bossio</strong><p>Acompañar el movimiento.</p><p class="tiny" style="margin-top:15px">Este enlace muestra tu rutina vigente. Volvé a abrirlo para consultar los cambios.</p>${!isPreview?'<button class="text-btn" data-action="refresh-patient" style="margin:10px auto">Actualizar rutina</button>':''}</footer></main>`;bind();bindPatientVideos(items)}

function bindPatientVideos(items){document.querySelectorAll('[data-patient-video]').forEach(button=>button.onclick=()=>{const item=items[Number(button.dataset.patientVideo)];if(!item)return;modal(esc(item.exercise.name),`<div class="patient-video-large">${mediaHTML(item.exercise)}</div><div class="dialog-footer"><button class="btn secondary" data-action="close">Cerrar video y volver a la rutina</button></div>`,true);bindVideos(dialog)})}
async function removePlanItem(index){const item=draft?.items[index];if(!item)return;if(!await confirmDialog('¿Quitar '+esc(item.exercise.name)+' de esta rutina?','Solo se quita de este paciente. El ejercicio sigue disponible en tu biblioteca. Después apretá Guardar cambios.'))return;const currentIndex=draft.items.indexOf(item);if(currentIndex<0)return;draft.items.splice(currentIndex,1);markDirty();renderEditor();toast('Ejercicio quitado. Guardá los cambios para actualizar el enlace del paciente.')}

async function loadPatient(){app.innerHTML='<main class="loading">Buscando tu rutina…</main>';try{if(!config.supabaseUrl)throw Error('Esta página todavía está en preparación. Tu profesional te enviará el enlace cuando esté habilitada.');const r=await api('/rest/v1/rpc/get_patient_routine',{method:'POST',body:JSON.stringify({p_token:patientToken})},false);if(!r)throw Error('La rutina no está disponible. Puede estar pausada o el enlace no ser correcto. Consultá con Tomás.');patientView(r)}catch(e){app.innerHTML=`<main class="auth-wrap"><div class="panel">${brand()}<h1 style="margin-top:25px">No pudimos abrir tu rutina.</h1><p class="muted">${esc(e.message)}</p>${btn('Volver a intentar','refresh-patient','secondary')}</div></main>`;bind()}}
function renderSettings(){shell(`<div class="page-heading"><div><p class="eyebrow" style="margin:0 0 9px">UN ESPACIO PROPIO</p><h1>Todo en su lugar.</h1><p>Tu biblioteca y tus rutinas, separadas de KINÉDATA.</p></div></div><div class="editor-layout"><section class="panel"><h2 style="margin-bottom:15px">${demo?'Conectar tu cuenta gratuita':'Tu cuenta está conectada'}</h2><p class="small muted">${demo?'La página ya está preparada para guardar rutinas en línea con Supabase. Para habilitar los enlaces reales hay que completar esta configuración inicial.':'Las rutinas se guardan en tu base de datos. Los pacientes acceden con su enlace y no necesitan registrarse.'}</p><div class="setup-steps"><div class="setup-step"><h3>Crear tu proyecto gratuito</h3><p>Creá una cuenta en <a href="https://supabase.com/dashboard" target="_blank" rel="noopener noreferrer">Supabase</a> y un proyecto con plan Free. No hace falta contratar un plan pago.</p></div><div class="setup-step"><h3>Preparar la base de datos y tu acceso</h3><p>El archivo de instalación crea las tablas y las reglas de acceso. El administrador se habilita con el correo que vos elijas; no hay registro público.</p><a class="text-btn" href="instalacion.sql" download>Descargar instalación SQL ${icon('download')}</a></div><div class="setup-step"><h3>Configurar la página una sola vez</h3><p>Hay que colocar la URL del proyecto y su clave pública en config.json. Nunca uses una clave secreta ni service_role. Te acompaño en este paso.</p></div><div class="setup-step"><h3>Publicar en tu alojamiento independiente</h3><p>Los archivos de la página se pueden alojar en GitHub Pages. Así el uso no depende de ChatGPT Plus. La página se puede usar desde tu enlace publicado.</p></div></div><div class="notice warn" style="margin-top:20px">${demo?'Todavía no compartas esta prueba con pacientes. La conexión en línea y el alojamiento independiente están pendientes.':'El alojamiento y la base de datos tienen sus propios límites y condiciones de servicio.'}</div></section><aside><div class="panel"><h3>Copias de tus datos</h3><p class="small muted">Descargá tus ejercicios y rutinas como respaldo. El archivo incluye enlaces a los videos, no los videos; conservá también los originales. La restauración del respaldo requiere asistencia técnica.</p><div class="action-stack" style="margin-top:18px">${btn('Descargar respaldo','export','secondary','download')}${btn('Administrar videos propios','manage-videos','secondary','video')}${demo?btn('Reiniciar prueba','reset-demo','ghost'):btn('Cerrar sesión','logout','ghost','logout')}</div></div><div class="panel" style="margin-top:20px"><h3>Videos propios</h3><p class="small muted">Se guardan una sola vez, hasta 50 MB por archivo. YouTube evita consumir ese espacio. Seleccionar un fragmento controla la reproducción, sin recortar físicamente el archivo.</p></div></aside></div>`)}
function renderLogin(){app.innerHTML=`<main id="main" class="auth-wrap">${brand()}<section class="panel"><span class="eyebrow muted">TU ESPACIO PROFESIONAL</span><h1 style="margin-top:15px">Qué bueno verte.</h1><p class="muted">Ingresá para administrar tus ejercicios y rutinas.</p><form id="login-form"><div id="login-error" class="error-text" role="alert"></div><label class="field">Correo electrónico<input name="email" type="email" autocomplete="username" required></label><label class="field">Contraseña<input name="password" type="password" autocomplete="current-password" required></label><button class="btn" type="submit">Ingresar ${icon('arrow')}</button></form></section><p class="tiny muted" style="text-align:center;margin-top:20px">Tomás Bossio · Plan de rutina</p></main>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const values=Object.fromEntries(new FormData(e.target));const r=await fetch(config.supabaseUrl+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:config.publishableKey,'Content-Type':'application/json'},body:JSON.stringify(values)});if(!r.ok)throw Error('No pudimos ingresar. Revisá tu correo y contraseña.');session=await r.json();sessionStorage.setItem('plan-session',JSON.stringify(session));const allowed=await api('/rest/v1/rpc/is_plan_admin',{method:'POST',body:'{}'});if(!allowed){session=null;sessionStorage.removeItem('plan-session');throw Error('Esta cuenta no tiene permiso para administrar los planes.')}await loadData();renderLibrary()}catch(err){$('#login-error').textContent=err.message;b.disabled=false}}}
function renderIntro(){startDemo()}
function startDemo(){demo=true;try{const saved=JSON.parse(localStorage.getItem('plan-rutina-demo-v1'));data=saved?.exercises&&saved?.routines?saved:demoSeed()}catch{data=demoSeed()}renderLibrary()}
async function navigate(id){if(dirty&&current==='editor'&&id!=='editor'){if(!await confirmDialog('¿Salir sin guardar?','Los cambios de esta rutina todavía no se guardaron.'))return;dirty=false}stopMedia(document);current=id;if(id==='library')renderLibrary();else if(id==='routines')renderRoutines();else renderSettings();window.scrollTo(0,0)}
function exportData(){const blob=new Blob([JSON.stringify({format:'plan-de-rutina-v1',exportedAt:new Date().toISOString(),...data},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='plan-de-rutina-respaldo-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function bind(root=document){root.querySelectorAll('[data-action]').forEach(el=>el.onclick=async ev=>{ev.preventDefault();const a=el.dataset.action,id=el.dataset.id;try{if(a==='brand'){if(patientToken||preview)window.scrollTo(0,0);else await navigate('library')}if(a==='nav')await navigate(id);if(a==='filter-block'){const y=window.scrollY;block=id;renderLibrary();window.scrollTo(0,y)}if(a==='open-catalogue')await openCatalogue();if(a==='new-exercise')exerciseForm();if(a==='edit-exercise')exerciseForm(id);if(a==='delete-exercise')await deleteExercise(id);if(a==='watch')watch(id);if(a==='close')closeModal();if(a==='start-demo')startDemo();if(a==='intro-settings'){startDemo();current='settings';renderSettings()}if(a==='new-routine'){newRoutine();window.scrollTo(0,0)}if(a==='edit-routine')editPlan(data.routines.find(r=>r.id===id));if(a==='assign'){modal('Agregar a una rutina',`<p class="small muted" style="margin-bottom:18px">Elegí un plan existente o creá uno nuevo.</p><div class="action-stack">${data.routines.map(r=>`<button class="btn secondary" data-add-plan="${esc(r.id)}">${esc(r.label)}</button>`).join('')}<button class="btn" id="assign-new">${icon('plus')}Crear una rutina</button></div>`);$('#assign-new').onclick=()=>{closeModal();newRoutine(id)};$$('[data-add-plan]').forEach(b=>b.onclick=()=>{const r=data.routines.find(x=>x.id===b.dataset.addPlan);draft=structuredClone(r);if(!draft.items.some(x=>x.exercise.id===id))draft.items.push(newPlanItem(getExercise(id)));dirty=true;current='editor';closeModal();renderEditor()})}if(a==='choose-exercises')chooseExercises();if(a==='remove-item')await removePlanItem(+id);if(a==='move-up'||a==='move-down'){const i=+id,j=i+(a==='move-up'?-1:1);moveItemToPosition(i,j)}if(a==='block-up'||a==='block-down'){const bs=planBlocks(draft),i=bs.indexOf(id),j=i+(a==='block-up'?-1:1);moveBlockToPosition(id,j)}if(a==='refresh-item'&&await confirmDialog('¿Actualizar desde la biblioteca?','Se reemplazan el video y las indicaciones generales de este ejercicio. Tus series, repeticiones y carga se conservan.')){const e=getExercise(draft.items[+id].exercise.id);if(e){draft.items[+id].exercise=exerciseSnap(e);markDirty();renderEditor()}}if(a==='duplicate-routine')await duplicateRoutine(data.routines.find(r=>r.id===id));if(a==='duplicate-draft')await duplicateRoutine(draft);if(a==='delete-routine')await deleteRoutine(data.routines.find(r=>r.id===id));if(a==='delete-draft')await deleteRoutine(draft);if(a==='clear-history')await deleteHistory(null);if(a==='delete-history-version')await deleteHistory(+id);if(a==='whatsapp-draft')whatsapp(draft);if(a==='manage-videos')await manageVideos();if(a==='save-routine')await saveRoutine();if(a==='preview-draft'){if(!draft.items.length){toast('Primero seleccioná algún ejercicio.');return}patientView(draft,true);window.scrollTo(0,0)}if(a==='preview-routine'){draft=structuredClone(data.routines.find(r=>r.id===id));dirty=false;patientView(draft,true);window.scrollTo(0,0)}if(a==='back-editor'){preview=false;current='editor';renderEditor()}if(a==='share-routine')share(data.routines.find(r=>r.id===id));if(a==='share-draft')share(draft);if(a==='history')await showHistory();if(a==='refresh-patient')await loadPatient();if(a==='export')exportData();if(a==='reset-demo'&&await confirmDialog('¿Reiniciar la prueba?','Esto borra únicamente los datos de ejemplo guardados en este navegador.')){data=demoSeed();storeDemo();current='library';renderLibrary()}if(a==='logout'){try{await api('/auth/v1/logout',{method:'POST'})}finally{session=null;sessionStorage.removeItem('plan-session');renderLogin()}}}catch(e){toast(e.message)}})}

async function duplicateRoutine(r){if(dirty&&draft?.id===r.id){toast('Guardá los cambios antes de duplicar la rutina.');return}modal('Duplicar rutina',`<p class="small muted">Se copian ejercicios e indicaciones a una rutina independiente, con un enlace nuevo.</p><form id="duplicate-form"><label class="field" style="margin-top:20px">Nombre y apellido del nuevo paciente<input name="label" required maxlength="80" placeholder="Nombre y apellido" autocomplete="off"></label><div class="dialog-footer"><button type="button" class="btn secondary" data-action="close">Cancelar</button><button type="submit" class="btn">Crear copia</button></div></form>`);$('#duplicate-form').onsubmit=ev=>{ev.preventDefault();const name=new FormData(ev.target).get('label').trim();if(data.routines.some(x=>normalizeName(x.label)===normalizeName(name))){toast('Ya existe una rutina para este nombre. Editá esa rutina.');return}draft={id:uid(),label:name,token:uid()+uid().replaceAll('-',''),items:structuredClone(r.items),blockOrder:planBlocks(r),note:r.note,active:true,revision:0};dirty=true;current='editor';closeModal();renderEditor();toast('Copia preparada. Revisala y guardá los cambios.')}}
async function deleteRoutine(r){if(!await confirmDialog('¿Eliminar la rutina de '+esc(r.label)+'?','Se eliminan la rutina y su historial. Su enlace dejará de funcionar. La biblioteca y sus videos se conservan. Esta acción no se puede deshacer.'))return;try{if(!demo)await api('/rest/v1/rpc/delete_plan_routine',{method:'POST',body:JSON.stringify({p_id:r.id,p_expected_revision:r.revision})});data.routines=data.routines.filter(x=>x.id!==r.id);if(demo)storeDemo();if(draft?.id===r.id){draft=null;dirty=false}current='routines';renderRoutines();toast('Rutina eliminada.')}catch(e){toast(e.message)}}
async function deleteHistory(revision){const id=draft.id;if(!await confirmDialog(revision===null?'¿Borrar todas las versiones anteriores?':'¿Eliminar la versión '+revision+'?', 'La rutina vigente y su enlace se conservan. El historial eliminado no se puede recuperar.'))return;try{if(demo){const r=data.routines.find(r=>r.id===id);r.history=revision===null?[]:(r.history||[]).filter(h=>h.revision!==revision);if(draft.id===id)draft.history=structuredClone(r.history);storeDemo()}else await api('/rest/v1/rpc/delete_plan_history',{method:'POST',body:JSON.stringify({p_id:id,p_revision:revision})});await showHistory();toast('Historial actualizado. La rutina vigente se conservó.')}catch(e){toast(e.message)}}
function whatsapp(r){if(demo){toast('WhatsApp se habilita al conectar tu cuenta y publicar los enlaces reales.');return}if(dirty&&draft?.id===r.id){toast('Guardá los cambios antes de preparar el mensaje.');return}if(!r.active){toast('Activá y guardá la rutina antes de compartirla.');return}const url=routineURL(r),first=`Hola, ${r.label}. Te comparto tu rutina de ejercicios para hacer en casa:\n${url}\nUsá este mismo enlace para consultar las próximas actualizaciones.`,update=`Hola, ${r.label}. Hice modificaciones en tu rutina de ejercicios. Podés verlas abriendo el mismo enlace:\n${url}`;modal('Compartir por WhatsApp',`<p class="small muted">Se abre WhatsApp con el mensaje preparado. Vos elegís el destinatario, revisás y enviás.</p><h3 class="defaults-title">Primera entrega</h3><p class="message-preview">${esc(first)}</p><a class="btn" href="https://wa.me/?text=${encodeURIComponent(first)}" target="_blank" rel="noopener noreferrer">Abrir WhatsApp</a><h3 class="defaults-title">Avisar una actualización</h3><p class="message-preview">${esc(update)}</p><a class="btn secondary" href="https://wa.me/?text=${encodeURIComponent(update)}" target="_blank" rel="noopener noreferrer">Avisar cambios por WhatsApp</a>`)}
async function manageVideos(){if(demo){modal('Videos propios',`<p class="small muted">Esta función se habilita al conectar tu cuenta. Vas a poder ver el espacio ocupado y eliminar videos que ya no estén en la biblioteca, las rutinas o su historial.</p><div class="notice" style="margin-top:18px">Los enlaces de YouTube no ocupan espacio de archivos en tu cuenta.</div>`);return}try{let files=[],offset=0,page=[];do{page=await api('/storage/v1/object/list/exercise-videos',{method:'POST',body:JSON.stringify({prefix:'',limit:100,offset,sortBy:{column:'name',order:'asc'}})});files.push(...page.filter(f=>f.id));offset+=100}while(page.length===100);const refs=new Set(await api('/rest/v1/rpc/get_plan_video_references',{method:'POST',body:'{}'}));const used=f=>[...refs].some(u=>u.endsWith('/exercise-videos/'+f.name)),size=files.reduce((sum,f)=>sum+Number(f.metadata?.size||0),0);modal('Administrar videos propios',`<p class="small muted">${files.length} archivos · ${(size/1048576).toFixed(1)} MB. Se pueden eliminar los archivos sin referencias. Para liberar uno en uso, quitá sus ejercicios y las versiones anteriores que lo conservan.</p><div class="video-file-list">${files.map(f=>`<div class="video-file-row"><div><strong>${esc(f.name)}</strong><small>${(Number(f.metadata?.size||0)/1048576).toFixed(1)} MB · ${used(f)?'En uso':'Sin uso'}</small></div><button class="icon-btn" data-remove-file="${esc(f.name)}" aria-label="Eliminar video ${esc(f.name)}" ${used(f)?'disabled':''}>${icon('trash')}</button></div>`).join('')||'<div class="notice" style="margin-top:20px">Todavía no hay archivos propios guardados.</div>'}</div>`);$$('[data-remove-file]').forEach(b=>b.onclick=async()=>{const name=b.dataset.removeFile;if(!await confirmDialog('¿Eliminar este archivo de video?','Se borra del almacenamiento de forma definitiva. Esta acción no se puede deshacer.'))return;try{const fresh=await api('/rest/v1/rpc/get_plan_video_references',{method:'POST',body:'{}'});if(fresh.some(u=>u.endsWith('/exercise-videos/'+name)))throw Error('El video está en uso. Quitá primero sus referencias.');await api('/storage/v1/object/exercise-videos',{method:'DELETE',body:JSON.stringify({prefixes:[name]})});await manageVideos();toast('Archivo eliminado del almacenamiento.')}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}

window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
dialog.addEventListener('close',()=>{stopMedia(dialog);if(pendingURL){URL.revokeObjectURL(pendingURL);pendingURL=null}pendingFile=null});
window.addEventListener('online',()=>{if(patientToken)loadPatient()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&patientToken)loadPatient()});
async function init(){try{const r=await fetch('config.json',{cache:'no-store'});if(!r.ok)throw Error('No se pudo leer la configuración.');config=await r.json();if(config.supabaseUrl)config.supabaseUrl=config.supabaseUrl.replace(/\/$/,'');if(patientToken){await loadPatient();return}if(!config.supabaseUrl||!config.publishableKey){renderIntro();return}try{session=JSON.parse(sessionStorage.getItem('plan-session'))}catch{}if(session){try{await loadData();renderLibrary()}catch{session=null;renderLogin()}}else renderLogin()}catch(e){app.innerHTML=`<main class="auth-wrap"><div class="panel"><h1>No pudimos iniciar.</h1><p>${esc(e.message)}</p><button class="btn" onclick="location.reload()">Volver a intentar</button></div></main>`}}

function matchesRegion(e,selectedRegion){return !selectedRegion||e.region===selectedRegion||Array.isArray(e.relatedRegions)&&e.relatedRegions.includes(selectedRegion)}
function applyCatalogueReview(previous,next,clinicianReviewed){const unchanged=previous.url===next.url&&previous.source===next.source&&(Number(previous.start)||0)===(Number(next.start)||0)&&(Number(previous.end)||0)===(Number(next.end)||0);next.reviewStatus=clinicianReviewed?'clinician_reviewed':unchanged&&previous.reviewStatus==='visual_sampled'?'visual_sampled':'source_checked';if(!unchanged){delete next.verification;next.reviewNote='Se modificó el video o su fragmento. La revisión visual anterior ya no corresponde a esta versión.';}return next}
function catalogueReviewBadge(e){return e.catalogueId?`<p class="catalogue-review-tag">${e.reviewStatus==='clinician_reviewed'?'Video revisado por vos':e.reviewStatus==='visual_sampled'?'Fragmento comprobado visualmente':'Fuente comprobada · revisión visual pendiente'}</p>`:''}
function catalogueMediaKey(e){const yt=youtubeId(e.url);return (yt?'youtube:'+yt:String(e.url||''))+'|'+(Number(e.start)||0)+'|'+(e.end?Number(e.end):'')}
function catalogueNewItems(items,existing){const ids=new Set(existing.map(e=>e.id)),media=new Set(existing.map(catalogueMediaKey)),names=new Set(existing.map(e=>norm(e.name||'').trim()+'|'+e.region+'|'+e.block));return items.filter(e=>!ids.has(e.id)&&!media.has(catalogueMediaKey(e))&&!names.has(norm(e.name||'').trim()+'|'+e.region+'|'+e.block))}
let catalogueCache=null,catalogueImportBusy=false;
async function readCatalogue(){if(catalogueCache)return catalogueCache;const response=await fetch('catalogo-ejercicios.json',{cache:'no-store'});if(!response.ok)throw Error('Falta el archivo catalogo-ejercicios.json. Subilo junto con app.js y style.css.');const bundle=await response.json();if(bundle.format!=='plan-rutina-catalogue'||!Array.isArray(bundle.exercises)||bundle.exercises.length>500)throw Error('El catálogo no tiene un formato válido.');for(const e of bundle.exercises){if(!/^[a-f0-9-]{36}$/i.test(e.id)||!e.name||!blocks.includes(e.block)||!regions.includes(e.region)||!safeUrl(e.url)||!['youtube','external'].includes(e.source)||e.source==='youtube'&&!youtubeId(e.url)||!Number.isFinite(e.start)||e.start<0||e.end!==null&&(!Number.isFinite(e.end)||e.end<=e.start))throw Error('Hay un ejercicio inválido en el catálogo.');}catalogueCache=bundle;return bundle}
async function importCatalogueItems(items){const fresh=catalogueNewItems(items,data.exercises);let added=0;if(demo){data.exercises=[...fresh.map(e=>structuredClone(e)),...data.exercises];storeDemo();return fresh.length}for(let i=0;i<fresh.length;i+=20){const batch=fresh.slice(i,i+20);await api('/rest/v1/exercises?on_conflict=id',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify(batch.map(e=>({id:e.id,content:e})))});added+=batch.length;const progress=$('#catalogue-progress');if(progress)progress.textContent='Guardando '+added+' de '+fresh.length+' ejercicios…';}await loadData();return added}
async function openCatalogue(){const bundle=await readCatalogue(),available=catalogueNewItems(bundle.exercises,data.exercises),selected=new Set();modal('Ampliar tu biblioteca',`<p class="small muted">${available.length} incorporaciones disponibles. Se agregan a tu biblioteca; no cambian las rutinas ni sus enlaces.</p><div class="notice"><p><strong>${bundle.reviewedCount||0} fragmentos comprobados visualmente por fotogramas.</strong> Podés ver el video, los tiempos y su fuente antes de elegirlo.</p><p>La cobertura todavía es parcial. Los candidatos pendientes están separados. Las dosis quedan vacías para que las definas vos; la revisión visual no reemplaza tu selección clínica.</p></div><div class="toolbar" style="margin-top:16px"><select id="catalogue-review" aria-label="Estado de revisión"><option value="reviewed">Fragmentos comprobados</option><option value="pending">Candidatos pendientes de revisión visual</option><option value="all">Todos</option></select><select id="catalogue-region" aria-label="Filtrar incorporaciones por región"><option value="">Todas las regiones</option>${regions.map(x=>`<option>${esc(x)}</option>`).join('')}</select><button class="btn secondary" type="button" id="catalogue-all">Seleccionar visibles</button><button class="btn secondary" type="button" id="catalogue-none">Quitar visibles</button></div><div id="catalogue-preview"></div><div id="catalogue-list"></div><details class="catalogue-pending"><summary>${(bundle.pending||[]).length} fuentes pendientes de recorte o compatibilidad</summary>${(bundle.pending||[]).map(e=>`<p><strong>${esc(e.name)}</strong><br>${esc(e.reason)}${safeUrl(e.url)?` · <a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Ver fuente</a>`:''}</p>`).join('')}</details><p id="catalogue-progress" class="small" role="status" aria-live="polite"></p><div class="dialog-footer"><button class="btn secondary" type="button" data-action="close">Cerrar</button><button class="btn" type="button" id="catalogue-import">Agregar seleccionados a mi biblioteca</button></div>`);const visible=()=>available.filter(e=>matchesRegion(e,$('#catalogue-region').value)&&($('#catalogue-review').value==='all'||($('#catalogue-review').value==='reviewed')===(e.reviewStatus==='visual_sampled')));const count=()=>{$('#catalogue-progress').textContent=selected.size+' ejercicios seleccionados';$('#catalogue-import').disabled=!selected.size||catalogueImportBusy};const draw=()=>{$('#catalogue-list').innerHTML=visible().map(e=>`<div class="catalogue-row"><label class="check-row"><input type="checkbox" data-catalogue-id="${esc(e.id)}" ${selected.has(e.id)?'checked':''}><span>${esc(e.name)}<small>${esc(e.region)} · ${esc(e.block)} · ${esc(e.author)}</small><small>${e.reviewStatus==='visual_sampled'?'Fragmento comprobado · '+esc(e.start)+'–'+esc(e.end)+' s':'Video completo · revisión visual pendiente'}</small></span></label><button class="icon-btn" type="button" data-catalogue-preview="${esc(e.id)}" aria-label="Previsualizar ${esc(e.name)}">${icon('play')}</button></div>`).join('')||'<p class="small muted">No hay incorporaciones nuevas en esta región.</p>';$$('[data-catalogue-id]').forEach(el=>el.onchange=()=>{el.checked?selected.add(el.dataset.catalogueId):selected.delete(el.dataset.catalogueId);count()});$$('[data-catalogue-preview]').forEach(el=>el.onclick=()=>{const e=available.find(e=>e.id===el.dataset.cataloguePreview);$('#catalogue-preview').innerHTML=`<section class="catalogue-media-preview"><h3>${esc(e.name)}</h3><p class="small">${e.end?'Fragmento: '+esc(e.start)+'–'+esc(e.end)+' segundos':'Video completo'}</p><div class="media-wrap">${mediaHTML(e)}</div><p class="small muted">${esc(e.reviewNote)}</p><a href="${esc(e.sourcePage)}" target="_blank" rel="noopener noreferrer">Fuente: ${esc(e.author)}</a><button class="text-btn" type="button" id="catalogue-close-preview">Cerrar video</button></section>`;bindVideos($('#catalogue-preview'));$('#catalogue-close-preview').onclick=()=>$('#catalogue-preview').replaceChildren();$('#catalogue-preview').scrollIntoView({block:'nearest'})});count()};$('#catalogue-region').onchange=draw;$('#catalogue-review').onchange=draw;$('#catalogue-all').onclick=()=>{visible().forEach(e=>selected.add(e.id));draw()};$('#catalogue-none').onclick=()=>{visible().forEach(e=>selected.delete(e.id));draw()};$('#catalogue-import').onclick=async()=>{if(catalogueImportBusy)return;catalogueImportBusy=true;count();const wanted=available.filter(e=>selected.has(e.id));try{const added=await importCatalogueItems(wanted);closeModal();renderLibrary();toast(added+' ejercicios incorporados'+(demo?' en la prueba de este navegador.':' a tu biblioteca.'))}catch(error){if(!demo)try{await loadData()}catch{}const progress=$('#catalogue-progress');if(progress)progress.textContent='No se completó la carga: '+error.message+'. Los ejercicios ya agregados se conservan. Cerrá y reintentá; no se duplican.';}finally{catalogueImportBusy=false;const b=$('#catalogue-import');if(b)b.disabled=!selected.size}};draw()}

init();
